<?php
require_once __DIR__ . '/layout.php';$uid=(int)$_SESSION['user_id'];$fy=(int)($_GET['fy']??leave_fiscal_year());$status=trim((string)($_GET['status']??''));
$where="handover_user_id={$uid} AND fiscal_year={$fy}";if(in_array($status,array('pending','accepted','rejected'),true))$where.=" AND handover_status='".$conn->real_escape_string($status)."'";$rows=array();$res=$conn->query("SELECT * FROM leave_applications WHERE {$where} ORDER BY (handover_status='pending') DESC,id DESC");while($res&&$r=$res->fetch_assoc())$rows[]=$r;
leave_page_start('งานที่รับมอบ','รายการที่เพื่อนร่วมงานส่งมอบให้คุณดูแลในช่วงวันลา','handover');
?>
<section class="leave-card"><div class="leave-card__head"><div><h2>รายการรับมอบงาน</h2><p>กรุณาตรวจสอบช่วงวันลาและยืนยันรับมอบงานก่อนส่งต่อหัวหน้างาน</p></div></div><div class="leave-card__body"><form class="leave-filter" method="get"><div class="leave-field"><label>ปีงบประมาณ</label><select class="leave-select" name="fy"><?php for($y=leave_fiscal_year()+1;$y>=leave_fiscal_year()-4;$y--):?><option value="<?=$y?>" <?=$fy===$y?'selected':''?>><?=$y?></option><?php endfor;?></select></div><div class="leave-field"><label>สถานะรับมอบ</label><select class="leave-select" name="status"><option value="">ทั้งหมด</option><option value="pending" <?=$status==='pending'?'selected':''?>>รอรับมอบงาน</option><option value="accepted" <?=$status==='accepted'?'selected':''?>>รับมอบงานแล้ว</option><option value="rejected" <?=$status==='rejected'?'selected':''?>>ส่งคืนให้แก้ไข</option></select></div><button class="leave-btn leave-btn--secondary">แสดงข้อมูล</button></form></div><div class="leave-table-wrap"><table class="leave-table"><thead><tr><th>เลขที่</th><th>ผู้ลา</th><th>ประเภท</th><th>ช่วงวันลา</th><th>จำนวนวัน</th><th>เหตุผล</th><th>สถานะรับมอบ</th><th>คำสั่ง</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="leave-empty">ไม่มีรายการรับมอบงาน</div></td></tr><?php endif;?><?php foreach($rows as $r):$hi=leave_handover_info($r['handover_status']);?><tr><td><strong><?=leave_e($r['leave_no'])?></strong></td><td><?=leave_e($r['employee_name'])?><br><small><?=leave_e($r['department_name'])?></small></td><td><?=leave_e($r['leave_type_name'])?></td><td><?=leave_date_thai($r['start_date'])?> – <?=leave_date_thai($r['end_date'])?></td><td><?=leave_format_days($r['leave_days'])?> วัน</td><td class="reason"><?=leave_e($r['reason'])?></td><td><span class="leave-badge leave-badge--<?=$hi[1]?>"><?=leave_e($hi[0])?></span></td><td><a class="leave-btn leave-btn--sm leave-btn--primary" href="detail.php?id=<?=$r['id']?>"><?=$r['handover_status']==='pending'?'ดำเนินการ':'รายละเอียด'?></a></td></tr><?php endforeach;?></tbody></table></div></section>
<?php leave_page_end(); ?>
